import{_ as a,c as t,o as n,ag as s}from"./chunks/framework.CoPVQkzc.js";const c=JSON.parse('{"title":"Data Pruning and Maintenance","description":"Message retention and cleanup","frontmatter":{"title":"Data Pruning and Maintenance","description":"Message retention and cleanup"},"headers":[],"relativePath":"engine/data_pruning_and_maintenance.md","filePath":"engine/data_pruning_and_maintenance.md","lastUpdated":1788476353000}'),r={name:"engine/data_pruning_and_maintenance.md"};function i(o,e,d,l,h,g){return n(),t("div",null,e[0]||(e[0]=[s(`<h1 id="data-pruning-and-maintenance" tabindex="-1">Data Pruning and Maintenance <a class="header-anchor" href="#data-pruning-and-maintenance" aria-label="Permalink to &quot;Data Pruning and Maintenance&quot;">​</a></h1><p>OIE stores message data in the database. Without regular maintenance, this data can grow unbounded and impact performance. The Data Pruner automates message cleanup.</p><h2 id="data-pruner" tabindex="-1">Data Pruner <a class="header-anchor" href="#data-pruner" aria-label="Permalink to &quot;Data Pruner&quot;">​</a></h2><p>The Data Pruner is a built-in plugin that automatically removes old message data based on configurable retention policies.</p><h3 id="accessing-the-data-pruner" tabindex="-1">Accessing the Data Pruner <a class="header-anchor" href="#accessing-the-data-pruner" aria-label="Permalink to &quot;Accessing the Data Pruner&quot;">​</a></h3><p>Navigate to <strong>Settings &gt; Data Pruner</strong> in the Administrator.</p><h3 id="global-settings" tabindex="-1">Global settings <a class="header-anchor" href="#global-settings" aria-label="Permalink to &quot;Global settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>Enable/disable the data pruner (disabled by default)</td></tr><tr><td><strong>Pruning Schedule</strong></td><td>Interval, daily time, or cron expression for when pruning runs</td></tr><tr><td><strong>Pruning Block Size</strong></td><td>Number of messages processed per pruning batch (default 1000; range 50 to 10000)</td></tr><tr><td><strong>Archiving Enabled</strong></td><td>Enable message archiving before pruning (disabled by default)</td></tr><tr><td><strong>Archiver Block Size</strong></td><td>Number of messages per archiver batch (default 50; max 1000)</td></tr><tr><td><strong>Include Attachments</strong></td><td>Include message attachments in archives (disabled by default)</td></tr><tr><td><strong>Prune Events</strong></td><td>Enable pruning of server events</td></tr><tr><td><strong>Max Event Age</strong></td><td>Maximum age of events to retain when event pruning is enabled</td></tr></tbody></table><h3 id="per-channel-pruning" tabindex="-1">Per-channel pruning <a class="header-anchor" href="#per-channel-pruning" aria-label="Permalink to &quot;Per-channel pruning&quot;">​</a></h3><p>Each channel can have its own pruning settings configured in the channel properties:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Prune metadata older than N days</strong></td><td>Remove message metadata after this many days</td></tr><tr><td><strong>Prune content older than N days</strong></td><td>Remove message content (but keep metadata) after this many days</td></tr><tr><td><strong>Archive before pruning</strong></td><td>Write messages to archive before deletion (enabled by default)</td></tr><tr><td><strong>Prune errored messages</strong></td><td>Include errored messages in pruning (disabled by default; by default messages with ERROR, QUEUED, or PENDING status are skipped)</td></tr></tbody></table><h3 id="pruning-strategy" tabindex="-1">Pruning strategy <a class="header-anchor" href="#pruning-strategy" aria-label="Permalink to &quot;Pruning strategy&quot;">​</a></h3><p>The pruner operates in two phases:</p><ol><li><strong>Metadata Pruning</strong> - Removes entire messages (metadata, content, custom metadata, attachments, and connector messages) older than the metadata retention period</li><li><strong>Content Pruning</strong> - Removes only message content and attachments while preserving metadata, for messages older than the content retention period but newer than the metadata retention period</li></ol><p>This allows you to keep lightweight metadata longer than full content. For example:</p><ul><li>Keep content for 7 days (for troubleshooting)</li><li>Keep metadata for 30 days (for audit/reporting)</li></ul><h2 id="message-storage-modes" tabindex="-1">Message storage modes <a class="header-anchor" href="#message-storage-modes" aria-label="Permalink to &quot;Message storage modes&quot;">​</a></h2><p>Message storage settings work together with pruning to control data volume:</p><table tabindex="0"><thead><tr><th>Mode</th><th>What&#39;s Stored</th><th>Pruning Impact</th></tr></thead><tbody><tr><td><strong>Development</strong></td><td>All content types (raw, transformed, encoded, sent, response, maps, etc.)</td><td>Largest storage footprint</td></tr><tr><td><strong>Production</strong></td><td>Raw, encoded, sent, response, and maps (excludes processed raw, transformed, response transformed, and processed response)</td><td>Moderate storage</td></tr><tr><td><strong>Raw</strong></td><td>Only raw content (no maps, encoded, sent, or response content; message recovery and durability disabled)</td><td>Smaller storage</td></tr><tr><td><strong>Metadata</strong></td><td>Only custom metadata and attachments, no message content or maps (message recovery disabled)</td><td>Minimal storage</td></tr><tr><td><strong>Disabled</strong></td><td>Nothing stored</td><td>No pruning needed</td></tr></tbody></table><p>Set storage mode per-channel in the channel properties.</p><h2 id="manual-message-cleanup" tabindex="-1">Manual message cleanup <a class="header-anchor" href="#manual-message-cleanup" aria-label="Permalink to &quot;Manual message cleanup&quot;">​</a></h2><h3 id="desktop-administrator" tabindex="-1">Desktop Administrator <a class="header-anchor" href="#desktop-administrator" aria-label="Permalink to &quot;Desktop Administrator&quot;">​</a></h3><ol><li>Open the <strong>Message Browser</strong> for a channel</li><li>Use filters to find messages</li><li>Select messages and click <strong>Remove</strong></li></ol><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Remove all messages from all channels</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clearallmessages</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reset all channel statistics</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resetstats</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [lifetime]</span></span></code></pre></div><h3 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Remove all messages for a specific channel</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Requested-With: OpenIntegrationEngine&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin:admin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://localhost:8443/api/channels/{channelId}/messages/_removeAll&quot;</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <code>X-Requested-With</code> header is required on all API requests. Any non-empty value is accepted.</p></div><h2 id="database-tasks" tabindex="-1">Database Tasks <a class="header-anchor" href="#database-tasks" aria-label="Permalink to &quot;Database Tasks&quot;">​</a></h2><p>The <strong>Settings &gt; Database Tasks</strong> panel shows available database cleanup or optimization tasks. Tasks appear when applicable conditions are detected (e.g., legacy tables exist that can be removed). Each task can be triggered manually from the panel.</p><h2 id="performance-considerations" tabindex="-1">Performance considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance considerations&quot;">​</a></h2><ol><li><strong>Set appropriate storage modes</strong> - Don&#39;t store full content in production unless needed</li><li><strong>Enable pruning</strong> - Configure content pruning at 7-14 days and metadata pruning at 30-90 days</li><li><strong>Size the database</strong> - Ensure adequate disk space for your message volume</li><li><strong>Monitor queue sizes</strong> - Growing queues indicate delivery problems</li><li><strong>Use read-write split</strong> - Enable <code>database.enable-read-write-split = true</code> for better performance</li><li><strong>Connection pool sizing</strong> - Adjust <code>database.max-connections</code> based on channel count and throughput</li></ol><h2 id="archiving" tabindex="-1">Archiving <a class="header-anchor" href="#archiving" aria-label="Permalink to &quot;Archiving&quot;">​</a></h2><p>When archiving is enabled, the Data Pruner exports messages before deleting them:</p><ul><li>Individual messages are serialized as XML files</li><li>Files can optionally be bundled into compressed archives (ZIP, TAR, etc. via Apache Commons Compress)</li><li>The archive directory, file pattern, and compression format are all configurable</li><li>Attachment inclusion is optional (disabled by default)</li><li>Archives can be extracted back to the filesystem, but there is no built-in re-import to the database</li></ul><p>Configure archiving in the Data Pruner settings panel.</p><h2 id="monitoring-database-size" tabindex="-1">Monitoring database size <a class="header-anchor" href="#monitoring-database-size" aria-label="Permalink to &quot;Monitoring database size&quot;">​</a></h2><p>Keep an eye on:</p><ul><li><strong>Total database size</strong> on disk</li><li><strong>Per-channel message counts</strong> in the Administrator</li><li><strong>Queue depths</strong> for destinations</li><li><strong>Error counts</strong> (errored messages are retained until pruned)</li></ul><p>Use the <code>dump stats &quot;path&quot;</code> CLI command to export statistics to a file for analysis.</p>`,40)]))}const u=a(r,[["render",i]]);export{c as __pageData,u as default};
